-- APN-MED — Az allergológiai szakterület kiegészítése.
--
-- Három kórkép, az APN napi munkájához igazítva:
--   · gyógyszerallergia és a téves allergiacímke;
--   · IgE-közvetített ételallergia;
--   · atópiás dermatitis.
--
-- A gyógyszerallergia azért került az élre, mert itt a legnagyobb a felismerhető
-- haszon: a penicillin-allergia címkék nagy része téves, és a címke miatt szélesebb
-- spektrumú, kockázatosabb szert kap a beteg. Az irodalom szerint a kockázatbecslést
-- és a felülvizsgálatot megfelelő képzéssel nem szakorvos is elvégezheti.
--
-- Előfeltétel: a 0060 lefutott.

insert into public.diseases
  (slug, name, aliases, abbrev, specialty, score_ids, lab_ids, ekg_ids,
   guideline_kw, body, status, version)
values
  ('gyogyszerallergia', 'Gyógyszerallergia és a téves allergiacímke', '{"penicillinallergia","gyógyszer-túlérzékenység","antibiotikum-allergia"}', 'Gyógyszerallergia', 'Allergológia és klinikai immunológia', '{"penfast","news2"}', '{"crp","wbc","eos"}', '{}', '{"gyógyszerallergia","penicillin","allergiacímke"}', '{"brief_what": "Gyógyszer kiváltotta túlérzékenységi reakció — és az ennél jóval gyakoribb helyzet, amikor a dokumentációban szereplő allergiacímke nem felel meg valós allergiának.", "brief_why": "A penicillin-allergia címkék nagy része téves, a betegek jelentős hányada biztonsággal kaphatna béta-laktám szert. A téves címke szélesebb spektrumú, drágább és kockázatosabb kezeléshez vezet, ami rosszabb kimenetellel és több rezisztens fertőzéssel jár. A kockázatbecslés és a felülvizsgálat megfelelő képzéssel ápolói feladat lehet.", "when": ["A dokumentációban szereplő allergiacímke tisztázása felvételkor vagy antibiotikum-választás előtt", "Gyógyszer szedése közben vagy után jelentkező bőrtünet, duzzanat, láz", "Ismeretlen eredetű, gyógyszerhez időben köthető panasz", "Antibiotikum-választás olyan betegnél, akinél béta-laktám címke szerepel"], "examine": ["Mi történt pontosan: milyen tünet, mikor a szedés kezdetétől számítva", "Mennyi ideje volt a reakció — az öt évnél régebbi események kockázata alacsonyabb", "Kellett-e kezelés miatta: kórházi felvétel, adrenalin, szteroid", "Bőrtünet jellege: csalánkiütés, foltos kiütés, hólyagosodás, nyálkahártya-érintettség", "Szedett-e azóta hasonló szert, és mi történt", "A bőr és a nyálkahártyák megtekintése aktív reakció esetén"], "labs": "Az akut reakciónál a diagnózis klinikai. A vérkép eozinofília irányában tájékoztat, a máj- és vesefunkció a szervi érintettségről. A szérum-triptáz anafilaxia gyanújánál segít. A specifikus IgE és a bőrpróba szakellátásban történik, és nem minden gyógyszerre elérhető.", "ekg": "Nem a diagnózis eszköze; anafilaxiás reakciónál a monitorozás része.", "imaging": "Rutinszerűen nem szükséges.", "scores": "A PEN-FAST öt pontos skála a penicillin-allergia kockázatának becslésére. Három pont alatt alacsony kockázatú a címke, és az irodalom szerint a felülvizsgálat bőrpróba nélkül, közvetlen szájon át adott próbadózissal elvégezhető — erre vonatkozó intézményi eljárásrend mellett.", "red_flags": ["Hólyagosodás, hámlás, nyálkahártya-érintettség — súlyos bőrreakció gyanúja, ilyenkor semmilyen újbóli adás nem jön szóba", "Láz, nyirokcsomó-duzzanat, arcduzzanat és szervi érintettség együtt — elhúzódó, súlyos gyógyszerreakció lehetősége", "Légúti tünet, vérnyomásesés — anafilaxia, azonnali ellátás", "Szemtünet vagy fájdalmas bőrpír", "Vesefunkció-romlás vagy májenzim-emelkedés a gyógyszer szedése alatt"], "apn_focus": ["Az allergiacímke tisztázása: pontosan mi történt, mikor, kellett-e kezelés — a puszta „allergiás a penicillinre\" bejegyzés önmagában használhatatlan", "A leírás rögzítése a dokumentációban a tünet megnevezésével, nem csak a gyógyszer nevével", "Az A típusú mellékhatás elkülönítése: a hányinger, a hasmenés vagy a fejfájás nem allergia, és nem indokolja a címkét", "A PEN-FAST szempontjainak ismerete és alkalmazása, ahol az intézményi rend engedi", "Aktív reakciónál a gyógyszer azonnali leállítása és a súlyossági jelek keresése", "A beteg tájékoztatása: mit jelent a címke, és miért érdemes tisztázni", "A felülvizsgálat eredményének visszavezetése a dokumentációba — enélkül a téves címke visszakerül"], "treatment": ["Aktív reakciónál a gyanúsított gyógyszer leállítása az első lépés", "Enyhe bőrtünetnél antihisztamin; anafilaxiánál izomba adott adrenalin", "Súlyos bőrreakció gyanúja esetén sürgős szakellátás; az újbóli adás ellenjavallt", "Alacsony kockázatú címke felülvizsgálata: intézményi eljárásrend szerint, megfigyelés mellett", "A béta-laktám szerek közötti keresztreakció kockázata kisebb, mint azt korábban feltételezték — a teljes csoport kizárása ritkán indokolt"], "followup": ["A tisztázott címke rögzítése és a felesleges bejegyzés törlése", "A betegnek szóló írásos tájékoztató arról, mi derült ki", "Szakellátási kivizsgálás bizonytalan vagy súlyos esetben", "A háziorvos értesítése a címke változásáról"], "source_name": "Penicillin-allergia felülvizsgálata: nemzetközi irányelvek rendszerezett áttekintése", "source_url": "https://onlinelibrary.wiley.com/doi/10.1111/cea.70269", "version": "2025", "updated": "2026-09-08", "evidence": "A közvetlen szájon át adott próbadózis biztonságossága alacsony kockázatú betegeknél jól alátámasztott. Az áttekintés ugyanakkor kimondja, hogy az irányelvek minősége összességében gyenge, és a kockázatbesorolásban jelentős eltérések vannak — ezért az intézményi eljárásrend nem hagyható el."}'::jsonb, 'published', '1'),
  ('etelallergia', 'IgE-közvetített ételallergia', '{"ételallergia","táplálékallergia","mogyoróallergia"}', 'Ételallergia', 'Allergológia és klinikai immunológia', '{"news2"}', '{"eos"}', '{}', '{"ételallergia","allergia","anafilaxia"}', '{"brief_what": "Meghatározott étel fogyasztására percek–két órán belül jelentkező, immunmechanizmusú túlérzékenységi reakció.", "brief_why": "Az anafilaxia egyik leggyakoribb kiváltója, különösen gyermekkorban. A kezelés súlypontja nem gyógyszeres: a kiváltó kerülése, az írásos vészhelyzeti terv és a beteg felkészítése dönti el, mi történik a következő reakciónál.", "when": ["Meghatározott étel fogyasztása után percekkel jelentkező tünetek", "Csalánkiütés, ajak- vagy szemduzzanat, hányás, hasi görcs", "Légúti tünet vagy vérnyomásesés — anafilaxia", "Ismétlődő, ugyanahhoz az ételhez köthető panasz"], "examine": ["Az étel és a tünet közötti időbeli összefüggés pontos rögzítése", "A tünetek köre: bőr, emésztés, légzés, keringés", "Korábbi reakciók súlyossága — a legutóbbi nem jelzi előre a következőt", "Társuló asztma keresése: rosszabbul kontrollált asztma súlyosabb reakcióval jár", "Tápláltsági állapot, különösen gyermeknél és több étel kerülése esetén"], "labs": "A specifikus IgE és a bőrpróba a kórelőzmény kiegészítője, nem helyettesíti azt: önmagában pozitív eredmény nem jelent allergiát. A megerősítés eszköze a szakellátásban végzett, ellenőrzött terheléses vizsgálat.", "ekg": "Nincs szerepe.", "imaging": "Nincs szerepe.", "scores": "Súlyossági pontozó nincs. Az anafilaxia felismerése klinikai; a NEWS2 az akut állapot követésére alkalmas.", "red_flags": ["Légúti tünet, hangváltozás, nyelési nehézség", "Vérnyomásesés, sápadtság, eszméletvesztés", "Rosszul kontrollált asztma az anamnézisben — súlyosabb reakció kockázata", "Több étel kerülése miatt kialakuló tápláltsági hiány, különösen gyermeknél", "Serdülő beteg — ebben az életkorban a legnagyobb a kockázatvállalás és a gyógyszer magánál hordásának elmulasztása"], "apn_focus": ["Írásos, személyre szabott vészhelyzeti terv: mit kell tenni, milyen sorrendben, kit kell hívni — a beteg és a hozzátartozó nyelvén", "Az adrenalin-autoinjektor használatának gyakoroltatása, nem csak elmagyarázása", "A címkeolvasás megtanítása és a rejtett összetevők kérdése", "Az asztma-kontroll ellenőrzése minden ételallergiás betegnél", "Iskolai, munkahelyi és étkeztetési tájékoztatás megszervezése", "A szorongás felmérése: az ételallergia jelentős lelki terhet ró a családra", "Serdülőknél külön beszélgetés a gyógyszer magánál hordásáról"], "treatment": ["A kiváltó étel kerülése, dietetikai támogatással", "Írásos kezelési terv és adrenalin-autoinjektor a kockázati profil szerint", "Akut reakciónál a súlyosság szerinti ellátás; anafilaxiánál izomba adott adrenalin", "Válogatott betegeknél orális immunterápia jön szóba, szakellátásban — ez deszenzitizálást ér el, nem gyógyulást"], "followup": ["A kezelési terv rendszeres felülvizsgálata, különösen életkorváltásnál", "Az autoinjektor lejáratának és a használati készség ellenőrzése", "A tolerancia kialakulásának követése — egyes ételallergiák gyermekkorban megszűnnek", "Tápláltsági állapot követése több étel kerülése esetén", "Lelki támogatás felajánlása jelentős szorongás esetén"], "source_name": "EAACI irányelv az IgE-közvetített ételallergia kezeléséről", "source_url": "https://onlinelibrary.wiley.com/doi/10.1111/all.16345", "version": "2024", "updated": "2026-09-08", "evidence": "A kerülés, az írásos terv és a beteg-oktatás alapvető ajánlás. Az orális immunterápia deszenzitizáló hatása igazolt, a tartós tolerancia kialakulása viszont bizonytalanabb."}'::jsonb, 'published', '1'),
  ('atopias-dermatitis', 'Atópiás dermatitis', '{"ekcéma","atópiás ekcéma","neurodermitis"}', 'AD', 'Allergológia és klinikai immunológia', '{}', '{"eos","crp"}', '{}', '{"atópiás dermatitis","ekcéma","bőrgyógyászat"}', '{"brief_what": "Krónikus, visszatérő, viszkető bőrgyulladás, amely a bőrgát működészavarán és gyulladásos folyamaton alapul.", "brief_why": "Gyakori, és a gyakorlatban gyakran alulkezelt. A kezelés sikere nagyrészt azon múlik, hogy a beteg helyesen és elég mennyiségben használja-e a készítményeket — ez pedig oktatási feladat. A viszketés és az alvászavar az életminőséget jelentősen rontja.", "when": ["Krónikus, visszatérő, viszkető bőrtünetek jellegzetes elhelyezkedéssel", "Csecsemőkorban arcon és a végtagok feszítő oldalán, később a hajlatokban", "Száraz bőr az egész testen, a tünetmentes időszakban is", "Atópiás betegségek a családban vagy a kórelőzményben"], "examine": ["A bőrtünetek kiterjedése, jellege, elhelyezkedése", "Fertőzés jelei: nedvedzés, sárgás pörk, fájdalom", "Karmolásnyomok, bőrmegvastagodás — a viszketés mértékére utal", "Az alvás minősége és a nappali működés terheltsége", "A jelenlegi kezelés: mit használ, mennyit, milyen gyakran"], "labs": "Rutinszerűen nem szükséges. Az összes IgE és az eozinofilszám gyakran emelkedett, de ez nem diagnosztikus. Allergiavizsgálat célzottan, ha a kórelőzmény kiváltóra utal.", "ekg": "Nincs szerepe.", "imaging": "Nincs szerepe.", "scores": "Az EASI és a SCORAD a súlyosság mérésére, az életminőség-kérdőívek a terhelés követésére szolgálnak. A napi viszketés-napló egyszerű és hasznos eszköz.", "red_flags": ["Nedvedzés, sárgás pörk, láz — bakteriális felülfertőződés", "Csoportos hólyagok, fájdalmas terjedő bőrtünet, rossz általános állapot — herpeszvírus okozta szövődmény, sürgős ellátást igényel", "Az egész testfelületre kiterjedő bőrpír", "Kezelésre nem javuló, atípusos elhelyezkedésű bőrtünet — más kórkép keresendő", "Növekedésbeli elmaradás gyermeknél tartós szteroidhasználat mellett"], "apn_focus": ["A helyi kezelés megtanítása: mennyit, hova, milyen gyakran — a leggyakoribb ok, amiért a kezelés nem hat, az elégtelen mennyiség és a szteroidfélelem", "A puhító készítmény napi, bőséges használatának magyarázata: ez a kezelés alapja, nem kiegészítő", "A szteroidfélelem oldása: a rövid, elegendő erősségű kezelés kevesebb szteroidot jelent, mint a hosszú, alulkezelt fellángolások sora", "A fürdetés és a bőrápolás sorrendjének megbeszélése", "A kaparás megtörése: körömvágás, hűtés, a viszketést kiváltó tényezők azonosítása", "Az alvászavar felmérése — ez terheli leginkább a családot", "A felülfertőződés jeleinek megtanítása"], "treatment": ["Puhító készítmény naponta, bőségesen — a kezelés alapja, tünetmentes időszakban is", "Fellángoláskor helyi szteroid, a testtájnak megfelelő erősségben, elegendő ideig", "Kalcineurin-gátló arcon és hajlatokban, illetve tartós kezelésnél", "Középsúlyos-súlyos, helyi kezelésre nem javuló esetben szakellátás: fényterápia vagy célzott biológiai kezelés", "A fertőzés kezelése, ha jelen van; megelőző antibiotikum nem javasolt"], "followup": ["A kezelés hatásának és a technika helyességének ellenőrzése néhány hét után", "A készítmény felhasználásának mennyiségi ellenőrzése — ebből derül ki, ha kevés", "Fellángolások gyakoriságának követése", "Az alvás és az életminőség rendszeres felmérése", "Gyermeknél a növekedés követése"], "source_name": "AAAAI/ACAAI közös munkacsoport irányelve az atópiás dermatitis kezeléséről", "source_url": "https://www.jaci-online.org/", "version": "2023", "updated": "2026-09-08", "evidence": "A puhító készítmények és a helyi gyulladáscsökkentők hatékonysága jól megalapozott. A biológiai kezelések bizonyítéka erős, elérhetőségük viszont országonként eltér."}'::jsonb, 'published', '1')
